/* ChartPulse — Shared Styles */
:root {
  --bg-primary: #0f0f0f;
  --bg-secondary: #161616;
  --bg-card: #1a1a2e;
  --bg-elevated: #1e1e30;
  --border: #2a2a3a;
  --text-primary: #e8e8f0;
  --text-secondary: #8888a8;
  --text-muted: #55556a;
  --accent-blue: #2962ff;
  --accent-blue-hover: #4070ff;
  --gain: #26a65b;
  --gain-bg: rgba(38,166,91,0.12);
  --loss: #f7525f;
  --loss-bg: rgba(247,82,95,0.12);
  --gold: #f5a623;
  --font: 'Inter', 'DM Sans', system-ui, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.5;
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
a:hover { color: var(--accent-blue); }

/* ─── Navigation ─── */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(15,15,15,0.95);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(12px);
  height: 52px;
  display: flex; align-items: center;
}
.nav-inner {
  max-width: 1400px; margin: 0 auto; padding: 0 20px;
  width: 100%;
  display: flex; align-items: center; gap: 32px;
}
.nav-logo {
  font-size: 18px; font-weight: 700;
  color: var(--accent-blue);
  letter-spacing: -0.5px;
  white-space: nowrap;
}
.nav-logo span { color: var(--text-primary); }
.nav-links { display: flex; gap: 4px; flex: 1; }
.nav-link {
  padding: 6px 12px; border-radius: 6px;
  font-size: 13px; font-weight: 500;
  color: var(--text-secondary);
  transition: all 0.15s;
  cursor: pointer;
}
.nav-link:hover, .nav-link.active { color: var(--text-primary); background: var(--bg-secondary); }
.nav-actions { display: flex; gap: 8px; align-items: center; }
.btn {
  padding: 7px 16px; border-radius: 6px;
  font-size: 13px; font-weight: 600;
  cursor: pointer; border: none;
  transition: all 0.15s;
}
.btn-ghost { background: transparent; color: var(--text-secondary); border: 1px solid var(--border); }
.btn-ghost:hover { color: var(--text-primary); border-color: var(--text-secondary); }
.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { background: var(--accent-blue-hover); }
.btn-sm { padding: 5px 12px; font-size: 12px; }

/* ─── Market Ticker Bar ─── */
.ticker-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  overflow: hidden;
  height: 36px;
  display: flex; align-items: center;
}
.ticker-inner {
  display: flex; gap: 0;
  overflow-x: auto; scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 0 20px;
}
.ticker-inner::-webkit-scrollbar { display: none; }
.ticker-item {
  display: flex; align-items: center; gap: 8px;
  padding: 0 16px; border-right: 1px solid var(--border);
  white-space: nowrap; flex-shrink: 0;
}
.ticker-name { color: var(--text-secondary); font-size: 12px; }
.ticker-price { font-weight: 600; font-size: 12px; }
.ticker-change { font-size: 11px; padding: 1px 5px; border-radius: 3px; }
.ticker-change.up { color: var(--gain); background: var(--gain-bg); }
.ticker-change.down { color: var(--loss); background: var(--loss-bg); }

/* ─── Tabs ─── */
.tabs {
  display: flex; gap: 2px;
  border-bottom: 1px solid var(--border);
  overflow-x: auto; scrollbar-width: none;
}
.tabs::-webkit-scrollbar { display: none; }
.tab {
  padding: 10px 16px;
  font-size: 13px; font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer; border-bottom: 2px solid transparent;
  white-space: nowrap; transition: all 0.15s;
  background: none; border-top: none; border-left: none; border-right: none;
}
.tab:hover { color: var(--text-primary); }
.tab.active { color: var(--text-primary); border-bottom-color: var(--accent-blue); }

/* ─── Cards ─── */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
}

/* ─── Change badges ─── */
.chg { font-size: 11px; font-weight: 600; padding: 2px 6px; border-radius: 4px; }
.chg.up { color: var(--gain); background: var(--gain-bg); }
.chg.down { color: var(--loss); background: var(--loss-bg); }
.chg.neutral { color: var(--text-secondary); background: var(--bg-secondary); }

/* ─── Tables ─── */
.data-table { width: 100%; border-collapse: collapse; }
.data-table th {
  text-align: left; color: var(--text-muted);
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.5px; padding: 8px 10px;
  border-bottom: 1px solid var(--border);
}
.data-table td {
  padding: 9px 10px;
  border-bottom: 1px solid rgba(42,42,58,0.5);
  font-size: 12px;
}
.data-table tr:hover td { background: rgba(255,255,255,0.02); }
.data-table tr:last-child td { border-bottom: none; }
.data-table td.right, .data-table th.right { text-align: right; }
.data-table td.mono { font-variant-numeric: tabular-nums; }

/* ─── Sparkline ─── */
.sparkline { display: inline-block; }

/* ─── Section headers ─── */
.section-title {
  font-size: 15px; font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 16px;
}
.section-subtitle {
  font-size: 12px; color: var(--text-secondary);
  margin-top: 4px; font-weight: 400;
}

/* ─── Grid layouts ─── */
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

/* ─── Container ─── */
.container { max-width: 1400px; margin: 0 auto; padding: 0 20px; }

/* ─── Footer ─── */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 40px 0 24px;
  margin-top: 60px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px;
  max-width: 1400px; margin: 0 auto; padding: 0 20px;
}
.footer-col h4 {
  font-size: 12px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.6px; color: var(--text-secondary);
  margin-bottom: 12px;
}
.footer-col a {
  display: block; color: var(--text-secondary);
  font-size: 12px; margin-bottom: 8px;
  transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  max-width: 1400px; margin: 24px auto 0; padding: 16px 20px 0;
  border-top: 1px solid var(--border);
  display: flex; justify-content: space-between; align-items: center;
}
.footer-bottom span { font-size: 11px; color: var(--text-muted); }

/* ─── Scrollbar ─── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-secondary); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .nav-links { display: none; }
}

