    .ideas-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
    .ideas-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
    .idea-card {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: 10px; overflow: hidden; cursor: pointer;
      transition: border-color 0.15s, transform 0.15s;
    }
    .idea-card:hover { border-color: var(--accent-blue); transform: translateY(-2px); }
    .idea-chart-thumb {
      height: 120px; position: relative; overflow: hidden;
      background: linear-gradient(135deg, #0d1a33, #1a1a2e);
    }
    .idea-chart-thumb svg { width: 100%; height: 100%; }
    .idea-direction-badge {
      position: absolute; top: 8px; left: 8px;
      padding: 3px 8px; border-radius: 4px; font-size: 10px; font-weight: 700;
      letter-spacing: 0.5px;
    }
    .badge-long { background: var(--gain); color: #fff; }
    .badge-short { background: var(--loss); color: #fff; }
    .badge-neutral { background: var(--text-muted); color: #fff; }
    .idea-body { padding: 14px; }
    .idea-ticker { font-size: 11px; font-weight: 700; color: var(--accent-blue); margin-bottom: 4px; }
    .idea-title { font-size: 13px; font-weight: 600; color: var(--text-primary); margin-bottom: 8px; line-height: 1.4; }
    .idea-meta { display: flex; gap: 12px; align-items: center; }
    .idea-author { font-size: 11px; color: var(--text-secondary); }
    .idea-stats { display: flex; gap: 8px; margin-left: auto; }
    .idea-stat { font-size: 11px; color: var(--text-muted); display: flex; align-items: center; gap: 3px; }

    /* ─── Indicators ─── */
    .indicators-section { padding: 32px 0; }
    .indicators-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
    .indicator-card {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: 10px; padding: 14px 16px;
      display: flex; gap: 12px; align-items: center;
      cursor: pointer; transition: border-color 0.15s;
    }
    .indicator-card:hover { border-color: var(--accent-blue); }
    .indicator-icon {
      width: 36px; height: 36px; border-radius: 8px;
      background: var(--bg-elevated); display: flex; align-items: center;
      justify-content: center; font-size: 16px; flex-shrink: 0;
    }
    .indicator-name { font-size: 13px; font-weight: 600; }
    .indicator-author { font-size: 11px; color: var(--text-secondary); }
    .indicator-tag {
      margin-left: auto; font-size: 10px; font-weight: 700;
      padding: 2px 7px; border-radius: 3px; flex-shrink: 0;
    }
    .tag-free { background: rgba(38,166,91,0.15); color: var(--gain); }
    .tag-pro { background: rgba(41,98,255,0.15); color: var(--accent-blue); }

    /* ─── Top Stories ─── */
    .stories-section { padding: 32px 0; }
    .stories-grid { display: grid; grid-template-columns: 2fr 1fr; gap: 20px; }
    .story-main {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: 10px; overflow: hidden;
    }
    .story-main-img {
      height: 200px; background: linear-gradient(135deg, #0d1a33, #1a2840);
      display: flex; align-items: center; justify-content: center;
      font-size: 40px;
    }
    .story-main-body { padding: 20px; }
    .story-tag { font-size: 11px; font-weight: 700; color: var(--accent-blue); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
    .story-title { font-size: 18px; font-weight: 700; line-height: 1.3; margin-bottom: 8px; }
    .story-desc { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }
    .story-side { display: flex; flex-direction: column; gap: 12px; }
    .story-card {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: 10px; padding: 14px;
      display: flex; gap: 12px; cursor: pointer; transition: border-color 0.15s;
    }
    .story-card:hover { border-color: var(--accent-blue); }
    .story-card-emoji { font-size: 22px; flex-shrink: 0; }
    .story-card-title { font-size: 13px; font-weight: 600; line-height: 1.3; margin-bottom: 4px; }
    .story-card-meta { font-size: 11px; color: var(--text-secondary); }

    /* ─── Trending Stocks ─── */
    .trending-section { padding: 32px 0; }
    .trending-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
    .trending-card {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: 10px; padding: 14px 16px;
      display: flex; justify-content: space-between; align-items: center;
      cursor: pointer; transition: border-color 0.15s;
    }
    .trending-card:hover { border-color: var(--accent-blue); }
    .trending-ticker { font-size: 14px; font-weight: 700; }
    .trending-company { font-size: 11px; color: var(--text-secondary); margin-top: 2px; max-width: 120px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .trending-right { text-align: right; }
    .trending-price { font-size: 14px; font-weight: 600; }
    .trending-pct { font-size: 12px; font-weight: 600; padding: 2px 7px; border-radius: 4px; margin-top: 3px; display: inline-block; }

    @media (max-width: 1200px) {
      .mkt-grid { grid-template-columns: repeat(3, 1fr); }
      .ideas-grid { grid-template-columns: 1fr 1fr; }
      .trending-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 768px) {
      .hero h1 { font-size: 28px; }
      .mkt-grid { grid-template-columns: 1fr 1fr; }
      .ideas-grid { grid-template-columns: 1fr; }
      .stories-grid { grid-template-columns: 1fr; }
      .hero-stats { gap: 20px; flex-wrap: wrap; }
    }
  </style>
</head>
