<script>
function scrollTo(id, el) {
  event.preventDefault();
  document.getElementById(id).scrollIntoView({ behavior: 'smooth', block: 'start' });
  document.querySelectorAll('.asset-tab').forEach(t => t.classList.remove('active'));
  el.classList.add('active');
}

function ctActive(btn) {
  const group = btn.parentElement;
  const sep = btn.previousElementSibling;
  // find the group this btn is in (time range vs chart type)
  const allBtns = group.querySelectorAll('.ct-btn');
  const sepIdx = Array.from(allBtns).findIndex(b => b.nextElementSibling && b.nextElementSibling.classList && b.nextElementSibling.classList.contains('ct-sep'));
  const btnIdx = Array.from(allBtns).indexOf(btn);
  if (btnIdx <= sepIdx) {
    // time range group
    Array.from(allBtns).slice(0, sepIdx+1).forEach(b => b.classList.remove('active'));
  } else {
    // chart type group
    Array.from(allBtns).slice(sepIdx+1).forEach(b => b.classList.remove('active'));
  }
  btn.classList.add('active');
}

function switchSession(btn, panelId) {
  document.querySelectorAll('.session-panel').forEach(p => p.style.display = 'none');
  document.querySelectorAll('.session-tab').forEach(t => t.classList.remove('active'));
  document.getElementById(panelId).style.display = 'block';
  btn.classList.add('active');
}
</script>
